-- DWM R2025b subsystem catalog, schema 2.
PRAGMA foreign_keys=OFF;
PRAGMA journal_mode=DELETE;
PRAGMA user_version=2;
BEGIN TRANSACTION;
CREATE TABLE block_products(block_id INTEGER NOT NULL REFERENCES blocks(id), product_code TEXT NOT NULL REFERENCES products(code), relationship TEXT NOT NULL DEFAULT 'library_owner_or_alternative' CHECK(relationship IN ('library_owner_or_alternative','assignment_requires_verification')), PRIMARY KEY(block_id,product_code));
CREATE TABLE block_sources(block_id INTEGER NOT NULL REFERENCES blocks(id), source_id INTEGER NOT NULL REFERENCES sources(id), PRIMARY KEY(block_id,source_id));
CREATE TABLE blocks(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, target_release TEXT NOT NULL DEFAULT 'R2025b', availability_status TEXT NOT NULL DEFAULT 'candidate_not_individually_release_verified', runtime_tested INTEGER NOT NULL DEFAULT 0 CHECK(runtime_tested IN (0,1)), introduced_release TEXT, notes TEXT NOT NULL DEFAULT '', entry_type TEXT NOT NULL DEFAULT 'component' CHECK(entry_type IN ('component','assembly')), classification_basis TEXT NOT NULL DEFAULT 'dwm_functional_boundary_v1', classification_rationale TEXT NOT NULL DEFAULT 'Individual modeled element or atomic function at the DWM catalog boundary; physical or software internals may contain multiple parts.');
CREATE TABLE catalog_requirements(id INTEGER PRIMARY KEY, requirement TEXT NOT NULL);
CREATE TABLE corrections(id INTEGER PRIMARY KEY, subsystem_id INTEGER REFERENCES subsystems(id), previous_entry TEXT NOT NULL, corrected_entry TEXT NOT NULL, rationale TEXT NOT NULL);
CREATE TABLE fluid_domains(code TEXT PRIMARY KEY, meaning TEXT NOT NULL);
CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE products(code TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, role TEXT NOT NULL);
CREATE TABLE sources(id INTEGER PRIMARY KEY, title TEXT NOT NULL, url TEXT NOT NULL UNIQUE, evidence_type TEXT NOT NULL);
CREATE TABLE subsystem_blocks(subsystem_id INTEGER NOT NULL REFERENCES subsystems(id), block_id INTEGER NOT NULL REFERENCES blocks(id), mapping_role TEXT NOT NULL DEFAULT 'candidate_component_or_alternative', PRIMARY KEY(subsystem_id,block_id));
CREATE TABLE subsystems(id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 25), name TEXT NOT NULL UNIQUE, components TEXT NOT NULL, applications TEXT NOT NULL, modeling_notes TEXT NOT NULL, target_release TEXT NOT NULL DEFAULT 'R2025b');
CREATE TABLE support_blocks(block_id INTEGER PRIMARY KEY REFERENCES blocks(id), purpose TEXT NOT NULL);
CREATE VIEW subsystem_catalog AS SELECT s.id AS priority,s.name AS subsystem,s.components,s.applications,s.modeling_notes,b.name AS block,b.target_release,b.availability_status,b.runtime_tested,b.notes AS block_notes,b.entry_type,b.classification_basis,b.classification_rationale,(SELECT group_concat(p.name, '; ') FROM block_products bp JOIN products p ON p.code=bp.product_code WHERE bp.block_id=b.id) AS products FROM subsystems s JOIN subsystem_blocks sb ON sb.subsystem_id=s.id JOIN blocks b ON b.id=sb.block_id;
COMMIT;
PRAGMA foreign_keys=ON;
