INSERT INTO "catalog_requirements" VALUES(1,'Parameterized CAD, explicit interfaces, and bill of materials per subsystem.');
INSERT INTO "catalog_requirements" VALUES(2,'Manufacturing, assembly, operation, maintenance, and repair instructions.');
INSERT INTO "catalog_requirements" VALUES(3,'Control firmware and simulation models where applicable.');
INSERT INTO "catalog_requirements" VALUES(4,'Operating limits, test procedures, assumptions, and verification evidence.');
INSERT INTO "catalog_requirements" VALUES(5,'Make locally / assemble locally / purchase classification; no classifications assigned yet.');
INSERT INTO "catalog_requirements" VALUES(6,'Qualify food-contact, drinking-water, high-pressure, and high-energy variants separately.');
INSERT INTO "catalog_requirements" VALUES(7,'Use matching fluid-property/settings blocks; fluid domain ports are not interchangeable.');
INSERT INTO "catalog_requirements" VALUES(8,'Do not double-count mass, friction, or screw constraints when coupling 1-D and 3-D models.');
INSERT INTO "catalog_requirements" VALUES(9,'Proposed first module: motor + matched drive + screw/belt transmission + guides + feedback + controller + protective controls.');
INSERT INTO "catalog_requirements" VALUES(10,'No complete process block is claimed for extrusion, cutting, welding, filtration capture, or casting.');
INSERT INTO "catalog_requirements" VALUES(11,'Recommended subsystem interfaces should be sized by requirements; one block family does not imply one physical size.');
INSERT INTO "corrections" VALUES(1,NULL,'R2011a compatibility caveat','Target MATLAB R2025b','User explicitly specified R2025b; do not assume installed products.');
INSERT INTO "corrections" VALUES(2,11,'Solid','Brick Solid; Cylindrical Solid; File Solid','Use specific geometry blocks.');
INSERT INTO "corrections" VALUES(3,13,'Solid','Brick Solid; Cylindrical Solid; File Solid','Use specific geometry blocks.');
INSERT INTO "corrections" VALUES(4,11,'Spring equivalents','Translational Spring; Rotational Spring; corresponding dampers','Use exact block names.');
INSERT INTO "corrections" VALUES(5,7,'Rigid or lumped shaft only','Add Flexible Cylindrical Beam','R2020a introduction documented.');
INSERT INTO "corrections" VALUES(6,11,'Rigid/lumped frame only','Add General Flexible Beam and Flexible Cylindrical Beam','Both predate R2025b.');
INSERT INTO "corrections" VALUES(7,12,'Rigid/lumped spindle only','Add Flexible Cylindrical Beam','Capture shaft flexibility.');
INSERT INTO "corrections" VALUES(8,24,'Base-Simscape Battery alternatives','Battery and Battery (Table-Based): EE or BAT; Battery Equivalent Circuit: BAT','Correct product ownership.');
INSERT INTO "corrections" VALUES(9,2,'Unversioned converter capabilities','Exclude ENA port and R2026a rectifier conduction-loss feature','Block exists in R2025b; newer options do not.');
INSERT INTO "corrections" VALUES(10,4,'Stateflow Chart','Chart (Stateflow)','Normalize actual block label.');
