INSERT INTO "metadata" VALUES('title','DWM community subsystem and MathWorks block catalog');
INSERT INTO "metadata" VALUES('target_release','R2025b');
INSERT INTO "metadata" VALUES('provenance','User-requested transcription of preceding 25-subsystem list, block mapping, and R2025b corrections.');
INSERT INTO "metadata" VALUES('scope','Engineering reference catalog; not a runtime economy/world-package database or installed block inventory.');
INSERT INTO "metadata" VALUES('verification','No MATLAB execution performed. Candidate entries retain uncertainty; documentation_reviewed records reflect sources examined in the preceding conversation, not an installed R2025b test.');
INSERT INTO "metadata" VALUES('ranking','Proposed reuse/manufacturing priority, not a schedule or permission to defer safety.');
INSERT INTO "metadata" VALUES('product_semantics','Multiple product owners can mean alternative library availability, not that every listed product must be purchased. Base MATLAB/Simulink/Simscape dependencies are not repeated per block.');
INSERT INTO "metadata" VALUES('mapping_semantics','A subsystem maps to candidate components or alternatives. Do not instantiate every block together or double-count inertia, friction, and constraints.');
INSERT INTO "metadata" VALUES('repository_selection','DWMStudio owns engineering workbench/reference data per Dream_World_Maker_Project_Goals.md. Neither inspected default branch had a tracked database directory; Databases is new.');
INSERT INTO "metadata" VALUES('source_repository_commit','cd240a19e73beabe37d6b8d32b3346b5a3e069b3');
INSERT INTO "metadata" VALUES('schema_version','2');
INSERT INTO "metadata" VALUES('classification_basis','dwm_functional_boundary_v1: component = individual modeled element or atomic function; assembly = interacting mechanism, circuit, combined controller, system or composition container. This is DWM editorial modeling classification, not MathWorks implementation metadata or a manufacturing BOM.');
INSERT INTO "metadata" VALUES('classification_scope','Every block has a binary entry_type and rationale. Support/configuration blocks are components. Physical devices may contain parts even when abstracted as a component. Reassess parameterized instances (especially batteries, imported solids and user functions) at the chosen engineering boundary.');
INSERT INTO "metadata" VALUES('classification_provenance','User requested assembly/component classification of existing catalog entries. Assigned from the represented functional boundary; MATLAB runtime and internal block implementation were not inspected.');
