INSERT INTO "subsystems" VALUES(1,'Electric motors','BLDC, stepper, brushed DC, induction variants','Pumps, machine tools, food processors, fans, vehicles, agriculture','Choose actual motor technology; servo adds drive, feedback and controller.','R2025b');
INSERT INTO "subsystems" VALUES(2,'Motor drives and controllers','ESCs, stepper drivers, servo drives, VFDs','Controlled speed, torque and positioning','Different drives require different power stages and controls.','R2025b');
INSERT INTO "subsystems" VALUES(3,'Electrical power conversion and distribution','Supplies, DC converters, harnesses, connectors, protection','Workshops, appliances, controls, mobile equipment','Model harness impedance and protection explicitly as appropriate.','R2025b');
INSERT INTO "subsystems" VALUES(4,'Machine controllers','Microcontroller/PLC modules, I/O, communications, operator panels','CNC, irrigation, printers, ovens, process equipment','Behavioral control model; hardware timing is not automatic.','R2025b');
INSERT INTO "subsystems" VALUES(5,'Sensors and feedback','Encoders, limits, temperature, pressure, flow, current, load','Accurate motion, process control, monitoring, faults','Ideal sensors need quantization, noise, delay and calibration for instrumentation realism. Fluid sensors must match domain.','R2025b');
INSERT INTO "subsystems" VALUES(6,'Machine safety and protective controls','E-stop, interlocks, guards, overload protection, shutdown','Every powered machine','Build fault/reset/shutdown logic plus physical switches/brakes. Assertion is a check, not a physical safety device.','R2025b');
INSERT INTO "subsystems" VALUES(7,'Rotary support assemblies','Shafts, bearings, housings, couplings, seals, lubrication','Wheels, spindles, pumps, mixers, turbines, gearboxes','Composite model. Bearing life, lubrication and leakage need added models.','R2025b');
INSERT INTO "subsystems" VALUES(8,'Mechanical transmissions','Gears, reducers, belts, chains, pulleys, brakes, clutches','Match motor speed/torque to loads','Use DL for power transmission or MB for spatial mechanisms; chain compliance/loss may require custom models.','R2025b');
INSERT INTO "subsystems" VALUES(9,'Screw-drive actuators','Lead/ball screws, nuts, supports, motor mounts','CNC axes, tables, positioning, screw presses','Leadscrew includes thread/friction; Lead Screw Joint provides 3-D coupling. Add preload/backlash/compliance as needed; avoid duplicate constraints.','R2025b');
INSERT INTO "subsystems" VALUES(10,'Linear guides and slides','Rails, carriages, bushings, ways, alignment','Routers, lathes, printers, saws, handling','Represent allowed motion, mass, friction, compliance and stops.','R2025b');
INSERT INTO "subsystems" VALUES(11,'Structural frames and machine beds','Bolted, welded, cast, extrusion structures and mounting','Machine tools, benches, carts, farm implements, enclosures','Rigid or flexible beam representation; detailed stress needs structural analysis. Generic Solid and Spring labels replaced by specific blocks.','R2025b');
INSERT INTO "subsystems" VALUES(12,'Spindles and toolholding','Spindles, chucks, collets, arbors, tool interfaces','Drilling, routing, milling, turning, grinding','Composite; cutting torque, imbalance, compliance and chatter require models/data.','R2025b');
INSERT INTO "subsystems" VALUES(13,'Workholding and fixtures','Vises, clamps, pins, jigs, molds, fixture plates','Repeatable machining, welding, assembly, casting','Fixed constraints or contact/actuators. Mold geometry is not casting physics.','R2025b');
INSERT INTO "subsystems" VALUES(14,'Metrology and calibration','Probes, gauges, reference surfaces, alignment, test rigs','Interchangeable parts, accuracy verification','Composite measurement chain with scale, offset, resolution, lag, noise and optional contact.','R2025b');
INSERT INTO "subsystems" VALUES(15,'Liquid pumping','Centrifugal, diaphragm, gear, peristaltic variants','Irrigation, water, coolant, food processing, dosing','Direct generic pump models; diaphragm/peristaltic pulsation may require custom displacement models.','R2025b');
INSERT INTO "subsystems" VALUES(16,'Fluid routing and filtration','Valves, manifolds, pipes, hoses, fittings, strainers, filters','Water, process plumbing, lubrication, coolant','Restriction approximates filter pressure drop; capture/clogging require added state equations.','R2025b');
INSERT INTO "subsystems" VALUES(17,'Hydraulic power and actuation','Power units, cylinders, valves, pressure protection','Presses, lifting, compactors, agricultural implements','Assemble pumps, reservoir, valves, actuators and load; thermal-liquid variants capture temperature.','R2025b');
INSERT INTO "subsystems" VALUES(18,'Pneumatic and vacuum systems','Compressors/vacuum pumps, conditioning, valves, cylinders, grippers','Clamping, handling, packaging, vacuum forming','Use absolute pressure and valid pump maps for vacuum. Suction seal/leak/holding force needs custom model.','R2025b');
INSERT INTO "subsystems" VALUES(19,'Controlled heating','Heaters/burners, insulation, regulation, thermal protection','Ovens, dryers, kilns, furnaces, heat treatment, hot water','Lumped thermal model; combustion, melting, transformations need additional physics.','R2025b');
INSERT INTO "subsystems" VALUES(20,'Cooling and heat transfer','Heat exchangers, coolant loops, refrigeration, insulation','Food preservation, cold storage, heat pumps, machine cooling','Use complete system-level cycle or assemble components with condenser and evaporator.','R2025b');
INSERT INTO "subsystems" VALUES(21,'Air movement and extraction','Fans, blowers, ducts, separators, filtration','Ventilation, crop drying, dust/fume extraction','Airflow/pressure/humidity model; particle separation/collection needs custom equations.','R2025b');
INSERT INTO "subsystems" VALUES(22,'Material feeding and extrusion','Rollers, augers, hoppers, metering, extrusion heads','3-D printers, filament, pellets, food processing','Composite feed/heating/melt-pressure/load model; rheology/conveying/deposition need custom equations.','R2025b');
INSERT INTO "subsystems" VALUES(23,'Cutting and joining process modules','Separate laser, plasma, welding, resistance joining variants','Sheet fabrication, frames, enclosures, repair, tooling','Custom process physics required; Weld Joint is rigid connection, not a welding-process simulation.','R2025b');
INSERT INTO "subsystems" VALUES(24,'Battery storage and charging','Battery modules, BMS, chargers, protective enclosures','Portable tools, carts, backup, renewable storage','Battery and table-based alternatives in EE/BAT, not base SC. Charging/balancing/protection/estimation are additional subsystems.','R2025b');
INSERT INTO "subsystems" VALUES(25,'Renewable-energy conversion','Generators, rectifiers, charge regulation, inverter interfaces','Wind, microhydro, solar infrastructure','Machine operated as generator; wind/water rotor torque and MPPT need their own models.','R2025b');
